<?php
if(!defined('ABSPATH'))exit;
function dgs_ta_tables(){global $wpdb;return ['days'=>$wpdb->prefix.'dgs_teacher_days','rows'=>$wpdb->prefix.'dgs_teacher_presence','audit'=>$wpdb->prefix.'dgs_teacher_presence_audit'];}
add_action('init',function(){if(get_option('dgs_teacher_att_schema')==='1')return;global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$t=dgs_ta_tables();$cc=$wpdb->get_charset_collate();
 dbDelta("CREATE TABLE {$t['days']} (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 school_year varchar(9) NOT NULL,
 school_day date NOT NULL,
 revision bigint(20) unsigned NOT NULL DEFAULT 1,
 PRIMARY KEY (id),
 UNIQUE KEY year_day (school_year,school_day)
 ) ENGINE=InnoDB $cc;");
 dbDelta("CREATE TABLE {$t['rows']} (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 school_year varchar(9) NOT NULL,
 school_day date NOT NULL,
 teacher_id bigint(20) unsigned NOT NULL,
 status varchar(12) NOT NULL,
 arrival varchar(5) NOT NULL DEFAULT '',
 departure varchar(5) NOT NULL DEFAULT '',
 note text NOT NULL,
 planned longtext NOT NULL,
 actor_id bigint(20) unsigned NOT NULL,
 updated_at datetime NOT NULL,
 PRIMARY KEY (id),
 UNIQUE KEY teacher_day (teacher_id,school_day),
 KEY year_day (school_year,school_day)
 ) ENGINE=InnoDB $cc;");
 dbDelta("CREATE TABLE {$t['audit']} (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 presence_id bigint(20) unsigned NOT NULL,
 actor_id bigint(20) unsigned NOT NULL,
 before_data longtext NOT NULL,
 after_data longtext NOT NULL,
 created_at datetime NOT NULL,
 PRIMARY KEY (id),
 KEY presence_history (presence_id)
 ) ENGINE=InnoDB $cc;");foreach($t as $table)if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)))!==$table)return;update_option('dgs_teacher_att_schema','1',false);
},20);
function dgs_ta_labels(){return ['present'=>'حاضر','absent'=>'غایب','late'=>'تأخیر','leave'=>'مرخصی','cancelled'=>'لغو جلسه'];}
function dgs_ta_plan($year,$day){global $wpdb;$e=dgs_edu_tables();$table=dgs_school_schedule_table();$weekday=((int)(new DateTimeImmutable($day))->format('w')+1)%7;$out=[];
 $plans=$wpdb->get_results($wpdb->prepare("SELECT t.*,c.title FROM $table t JOIN {$e['classes']} c ON c.id=t.class_id WHERE c.school_year=%s AND c.active=1",$year));foreach($plans as $plan){$periods=json_decode($plan->periods,true)?:[];foreach(json_decode($plan->cells,true)?:[] as $cell){if((int)($cell['day']??-1)!==$weekday)continue;$uid=(int)($cell['teacher_id']??0);if(!$uid||!dgs_edu_role($uid,'dgs_teacher'))continue;$slot=(int)($cell['slot']??0);$out[$uid][]=['class'=>$plan->title,'start'=>$periods[$slot]['start']??'','end'=>$periods[$slot]['end']??'','activity'=>$cell['activity']??''];}}
 return $out;
}
function dgs_ta_rows($year,$day){global $wpdb;$t=dgs_ta_tables();return $wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['rows']} WHERE school_year=%s AND school_day=%s",$year,$day),OBJECT_K);}
function dgs_ta_index($year,$day){$out=[];foreach(dgs_ta_rows($year,$day) as $r)$out[(int)$r->teacher_id]=$r;return $out;}
function dgs_ta_revision($year,$day){global $wpdb;$t=dgs_ta_tables();return (int)$wpdb->get_var($wpdb->prepare("SELECT revision FROM {$t['days']} WHERE school_year=%s AND school_day=%s",$year,$day));}
function dgs_ta_save($d){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','ثبت حضور دبیران فقط توسط مدیر و معاون است.');$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';$day=is_string($d['day']??null)?dgs_att_parse_day($d['day'],$year):false;$rev=$d['revision']??null;
 if(!$day||$day>dgs_att_today()||!is_scalar($rev)||!ctype_digit((string)$rev)||!is_array($d['teachers']??null)||count($d['teachers'])>500||get_option('dgs_teacher_att_schema')!=='1')return dgs_edu_error('input','روز معتبر حداکثر امروز و فرم معتبر انتخاب کنید.');
 $plan=dgs_ta_plan($year,$day);$saved=dgs_ta_index($year,$day);$clean=[];foreach($d['teachers'] as $id=>$row){if(!ctype_digit((string)$id)||!dgs_edu_role((int)$id,'dgs_teacher')||!is_array($row))return dgs_edu_error('teacher','دبیر معتبر انتخاب کنید.');foreach($row as $v)if(!is_scalar($v))return dgs_edu_error('input','ورودی معتبر نیست.');$status=(string)($row['status']??'');if($status==='')continue;if(!isset(dgs_ta_labels()[$status]))return dgs_edu_error('status','وضعیت معتبر نیست.');$arrival=dgs_edu_digits((string)($row['arrival']??''));$departure=dgs_edu_digits((string)($row['departure']??''));if(($arrival!==''&&!dgs_school_clock($arrival))||($departure!==''&&!dgs_school_clock($departure))||($departure!==''&&($arrival===''||$departure<$arrival)))return dgs_edu_error('clock','ساعت ورود و خروج ۲۴ساعته و به ترتیب باشند.');if(in_array($status,['absent','leave','cancelled'],true)&&($arrival!==''||$departure!==''))return dgs_edu_error('clock','برای غیبت، مرخصی یا لغو جلسه ساعت ورود و خروج وارد نکنید.');$note=sanitize_textarea_field((string)($row['note']??''));if(isset($saved[$id])&&$saved[$id]->status===$status&&$saved[$id]->arrival===$arrival&&$saved[$id]->departure===$departure&&$saved[$id]->note===$note)continue;if(dgs_edu_length($note)>1000||(!empty($saved[$id])&&$note==='')||(in_array($status,['leave','cancelled'],true)&&$note===''))return dgs_edu_error('note','برای اصلاح، مرخصی یا لغو جلسه توضیح بنویسید (حداکثر ۱۰۰۰ نویسه).');$clean[(int)$id]=['school_year'=>$year,'school_day'=>$day,'teacher_id'=>(int)$id,'status'=>$status,'arrival'=>$arrival,'departure'=>$departure,'note'=>$note,'planned'=>isset($saved[$id])?$saved[$id]->planned:wp_json_encode($plan[$id]??[['activity'=>'جلسه جبرانی / ثبت مدیریتی']]),'actor_id'=>get_current_user_id(),'updated_at'=>current_time('mysql')];}
 if(!$clean&&$saved)return 'تغییر جدیدی وجود ندارد؛ اطلاعات قبلی محفوظ است.';if(!$clean)return dgs_edu_error('empty','حداقل یک وضعیت انتخاب کنید؛ بدون ثبت به معنی حاضر نیست.');
 global $wpdb;$t=dgs_ta_tables();$wpdb->query('START TRANSACTION');try{$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['days']} WHERE school_year=%s AND school_day=%s FOR UPDATE",$year,$day));if((int)$rev!==($old?(int)$old->revision:0))throw new RuntimeException('اطلاعات هم‌زمان تغییر کرده؛ صفحه را تازه کنید.');if($old)$ok=$wpdb->update($t['days'],['revision'=>(int)$rev+1],['id'=>$old->id,'revision'=>(int)$rev]);else $ok=$wpdb->insert($t['days'],['school_year'=>$year,'school_day'=>$day,'revision'=>1]);if(!$ok)throw new RuntimeException('این روز هم‌زمان تغییر کرد؛ دوباره بارگذاری کنید.');
 foreach($clean as $id=>$row){$before=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['rows']} WHERE teacher_id=%d AND school_day=%s FOR UPDATE",$id,$day));if($before&&$before->school_year!==$year)throw new RuntimeException('سابقه این تاریخ متعلق به سال دیگری است.');$ok=$before?$wpdb->update($t['rows'],$row,['id'=>$before->id]):$wpdb->insert($t['rows'],$row);if($ok===false)throw new RuntimeException('ذخیره حضور انجام نشد.');$rid=$before?$before->id:$wpdb->insert_id;if(!$wpdb->insert($t['audit'],['presence_id'=>$rid,'actor_id'=>get_current_user_id(),'before_data'=>wp_json_encode($before),'after_data'=>wp_json_encode($row),'created_at'=>current_time('mysql')]))throw new RuntimeException('سابقه تغییر ذخیره نشد.');}
 if($wpdb->query('COMMIT')===false)throw new RuntimeException('ذخیره نهایی نشد.');return 'حضور دبیران ذخیره شد؛ سوابق تغییرات محفوظ است.';
 }catch(Throwable $e){$wpdb->query('ROLLBACK');return dgs_edu_error('write',$e->getMessage());}
}
add_action('admin_post_dgs_teacher_attendance',function(){if(!current_user_can('dgs_manage_education')||($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgs_teacher_attendance');$d=wp_unslash($_POST);$r=dgs_ta_save($d);$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,['error'=>is_wp_error($r),'text'=>is_wp_error($r)?$r->get_error_message():$r],300);$year=is_string($d['year']??null)?dgs_edu_year($d['year']):dgs_edu_current_year();wp_safe_redirect(dgs_school_url('teacher_attendance',$year,['ta_day'=>is_scalar($d['day']??null)?$d['day']:'','dg_notice'=>$token]),303);exit;});
function dgs_ta_form($year,$day){return '<form method="post" class="dgx-form" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_teacher_attendance','_wpnonce',true,false).'<input type="hidden" name="action" value="dgs_teacher_attendance"><input type="hidden" name="year" value="'.esc_attr($year).'"><input type="hidden" name="day" value="'.esc_attr(dgs_att_jdate($day)).'"><input type="hidden" name="revision" value="'.dgs_ta_revision($year,$day).'">';}
function dgs_ta_inputs($id,$row=null){$prefix='teachers['.$id.']';$h=dgs_edu_select($prefix.'[status]','وضعیت',dgs_ta_labels(),$row?$row->status:'',false);foreach(['arrival'=>'ورود واقعی','departure'=>'خروج واقعی'] as $key=>$label)$h.='<label>'.$label.'<input type="time" name="'.$prefix.'['.$key.']" value="'.esc_attr($row?$row->$key:'').'"></label>';$h.='<label>توضیح / دلیل اصلاح<input name="'.$prefix.'[note]" maxlength="1000" value="'.esc_attr($row?$row->note:'').'"></label>';return $h;}
function dgs_edu_view_teacher_attendance($year){
 if(!current_user_can('dgs_manage_education'))return '';$day=dgs_att_parse_day(dgs_att_get('ta_day',dgs_att_jdate(dgs_att_today())),$year)?:dgs_att_parse_day(dgs_att_default_day($year),$year);$start=(new DateTimeImmutable($day))->modify('-'.(((int)(new DateTimeImmutable($day))->format('w')+1)%7).' days');$plan=dgs_ta_plan($year,$day);$saved=dgs_ta_index($year,$day);$ids=array_unique(array_merge(array_keys($plan),array_keys($saved)));$teacher=absint(dgs_att_get('ta_teacher'));
 $h='<div class="dsp-school dgx-teacher-att">'.dgs_extension_title('حضور و غیاب دبیران','teacher_attendance','ثبت روزانه با تاریخ؛ فقط مدیر و معاون. فهرست از برنامه هفتگی می‌آید و روز بدون ثبت، حاضر محسوب نمی‌شود.').'<section class="dsp-card"><form class="dgx-filter" method="get"><input type="hidden" name="dg_tab" value="teacher_attendance"><input type="hidden" name="dg_year" value="'.esc_attr($year).'"><label>تاریخ شمسی<input name="ta_day" dir="ltr" value="'.esc_attr(dgs_att_jdate($day)).'"></label>'.dgs_edu_select('ta_teacher','گزارش یک دبیر',dgs_edu_user_options('dgs_teacher'),$teacher,false).'<button class="dg-btn">نمایش هفته / گزارش</button></form><nav class="dgx-week">';for($i=0;$i<7;$i++){$date=$start->modify('+'.$i.' days')->format('Y-m-d');if(!dgs_att_parse_day(dgs_att_jdate($date),$year))continue;$n=count(dgs_ta_plan($year,$date));$h.='<a '.($date===$day?'aria-current="page"':'').' href="'.esc_url(dgs_school_url('teacher_attendance',$year,['ta_day'=>dgs_att_jdate($date),'ta_teacher'=>$teacher])).'">'.esc_html(dgs_fa_digits(dgs_att_jdate($date))).'<small>'.esc_html(dgs_fa_digits($n)).' دبیر برنامه‌ریزی‌شده</small></a>';}$h.='</nav></section>';
 $h.='<section class="dsp-card"><h3>ثبت روز '.esc_html(dgs_fa_digits(dgs_att_jdate($day))).'</h3>'.dgs_ta_form($year,$day).'<div class="dgx-table">'.dgs_edu_table_start(['دبیر / برنامه','وضعیت و ساعت‌ها']);foreach($ids as $id){$u=get_userdata($id);if(!$u)continue;$h.='<tr><td>'.esc_html($u->display_name);$slots=isset($saved[$id])?(json_decode($saved[$id]->planned,true)?:[]):($plan[$id]??[]);foreach($slots as $slot)$h.='<small>'.esc_html(($slot['class']??$slot['activity']??'').' '.($slot['start']??'').' — '.($slot['end']??'')).'</small>';if(isset($saved[$id]))$h.='<small>ثبت‌کننده: '.esc_html(dgs_mark_actor($saved[$id]->actor_id)).' · '.esc_html($saved[$id]->updated_at).'</small>';$h.='</td><td><div class="dgx-input-row">'.dgs_ta_inputs($id,$saved[$id]??null).'</div></td></tr>';}$h.='</tbody></table></div></div>';if(!$ids)$h.='<p>برای این روز دبیری در برنامه ثبت نشده است؛ می‌توانید جلسه جبرانی اضافه کنید.</p>';$h.='<button class="dg-btn" '.($day>dgs_att_today()?'disabled':'').'>ذخیره وضعیت‌های انتخاب‌شده</button></form></section>';
 $manual=absint(dgs_att_get('ta_manual'));$h.='<details class="dsp-card"><summary>افزودن دبیر / جلسه جبرانی خارج از برنامه</summary><form method="get"><input type="hidden" name="dg_tab" value="teacher_attendance"><input type="hidden" name="dg_year" value="'.esc_attr($year).'"><input type="hidden" name="ta_day" value="'.esc_attr(dgs_att_jdate($day)).'">'.dgs_edu_select('ta_manual','دبیر',dgs_edu_user_options('dgs_teacher'),$manual).'<button class="dg-btn dg-btn-outline">انتخاب دبیر</button></form>';if($manual&&dgs_edu_role($manual,'dgs_teacher'))$h.=dgs_ta_form($year,$day).dgs_ta_inputs($manual,$saved[$manual]??null).'<button class="dg-btn">ثبت جلسه جبرانی</button></form>';$h.='</details>';
 if($teacher&&dgs_edu_role($teacher,'dgs_teacher')){global $wpdb;$t=dgs_ta_tables();$end=$start->modify('+6 days')->format('Y-m-d');$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['rows']} WHERE teacher_id=%d AND school_year=%s AND school_day BETWEEN %s AND %s ORDER BY school_day",$teacher,$year,$start->format('Y-m-d'),$end));$h.='<section class="dsp-card"><h3>گزارش هفتهٔ '.esc_html(dgs_mark_actor($teacher)).'</h3>'.dgs_edu_table_start(['روز','وضعیت','ورود / خروج','توضیح / تاریخچه']);foreach($rows as $r){$h.='<tr><td>'.esc_html(dgs_fa_digits(dgs_att_jdate($r->school_day))).'</td><td>'.esc_html(dgs_ta_labels()[$r->status]).'</td><td>'.esc_html($r->arrival.' / '.$r->departure).'</td><td>'.esc_html($r->note).'<details><summary>تاریخچه تغییرات</summary>';$audit=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['audit']} WHERE presence_id=%d ORDER BY id DESC LIMIT 50",$r->id));foreach($audit as $a){$before=json_decode($a->before_data,true);$after=json_decode($a->after_data,true);$h.='<p>'.esc_html(dgs_mark_actor($a->actor_id).' · '.$a->created_at).' · '.esc_html(($before['status']??'بدون ثبت').' ← '.($after['status']??'')).'<br>'.esc_html('ورود: '.($before['arrival']??'—').' ← '.($after['arrival']??'—').' | خروج: '.($before['departure']??'—').' ← '.($after['departure']??'—').' | توضیح: '.($before['note']??'—').' ← '.($after['note']??'—')).'</p>';}$h.='</details></td></tr>';}$h.='</tbody></table></div><button type="button" class="dg-btn dg-btn-outline" data-dgx-print>چاپ گزارش</button></section>';}
 return $h.'</div>';
}
